with kept_keys as (select status, order_id from shipments intersect all select status, order_id from shipments where status != 'LOST'), verified as (select s.* from shipments s inner join kept_keys k on s.status = k.status and s.order_id = k.order_id) select case when cost >= 78 then 'PREMIUM' else 'STANDARD' end as cost_tier, carrier, count(*) filter (where status = 'LOST') as lost_rows, sum(cost) filter (where status = 'DELIVERED') as delivered_total_cost, percentile_approx(cost, 0.9) as cost_p90, sum(case when carrier = 'Flash' then cost else 0 end) as flash_cost from verified group by case when cost >= 78 then 'PREMIUM' else 'STANDARD' end, carrier order by carrier desc nulls first;
